tool.command:

  ln -f -s ${input_model_pth_path} ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext};

  ln -f -s ${input_stats_pt_path} ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};

  ln -f -s ${input_reference_pdb_path} ${input_reference_pdb_path}_`echo $$`.${input_reference_pdb_path.ext};

  ln -f -s ${input_ndx_path} ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

make_plumed

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__include_energy__dq__:${properties.include_energy},__dq__bias__dq__:${properties.bias},__dq__prints__dq__:${properties.prints},__dq__group__dq__:${properties.group},__dq__wholemolecules__dq__:${properties.wholemolecules},__dq__fit_to_template__dq__:${properties.fit_to_template},__dq__pytorch_model__dq__:${properties.pytorch_model}__cc____cc__'
  #end if

  #if str($input_model_pth_path) != 'None':
    --input_model_pth_path ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext}
  #end if

  #if str($input_stats_pt_path) != 'None':
    --input_stats_pt_path ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext}
  #end if

  #if str($input_reference_pdb_path) != 'None':
    --input_reference_pdb_path ${input_reference_pdb_path}_`echo $$`.${input_reference_pdb_path.ext}
  #end if

  #if str($input_ndx_path) != 'None':
    --input_ndx_path ${input_ndx_path}_`echo $$`.${input_ndx_path.ext}
  #end if


  --output_plumed_dat_path $outname_output_plumed_dat_path

  --output_features_dat_path $outname_output_features_dat_path

  --output_model_ptc_path $outname_output_model_ptc_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_model_pth_path}_`echo $$`.${input_model_pth_path.ext};

  rm -f ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};

  rm -f ${input_reference_pdb_path}_`echo $$`.${input_reference_pdb_path.ext};

  rm -f ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};


  if test -f $outname_output_plumed_dat_path; then mv $outname_output_plumed_dat_path $output_plumed_dat_path; fi;

  if test -f $outname_output_features_dat_path; then mv $outname_output_features_dat_path $output_features_dat_path; fi;

  if test -f $outname_output_model_ptc_path; then mv $outname_output_model_ptc_path $output_model_ptc_path; fi;
